public class Cache<K, V> {
    private final Map<K, V> map = new HashMap<>();

    public V getOrCompute(K key, Function<K, V> compute) {
        if (!map.containsKey(key)) {
            V value = compute.apply(key);
            map.put(key, value);
        }
        return map.get(key);
    }
}
